package com.vibecode.prompt.application;
import com.vibecode.output.domain.TaskEvidence; import com.vibecode.project.application.ProjectService; import com.vibecode.project.domain.Project; import com.vibecode.prompt.domain.*; import com.vibecode.roadmap.application.*; import com.vibecode.task.domain.WorkflowTask; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DeterministicPromptBuilder {private final ProjectService projects; private final WorkflowService flow; private final ProjectStateService state; private final DeterministicNextStepEngine next; public DeterministicPromptBuilder(ProjectService p,WorkflowService f,ProjectStateService s,DeterministicNextStepEngine n){projects=p;flow=f;state=s;next=n;} public GeneratedPrompt generate(UUID projectId,UUID taskId,PromptType type){Project p=projects.get(projectId);WorkflowRecommendation r=next.recommend(projectId);WorkflowTask t=taskId==null?(r.taskId()==null?null:flow.requireTask(projectId,r.taskId())):flow.requireTask(projectId,taskId);String task=t==null?"Nenhuma tarefa selecionada":t.title()+"\nObjetivo: "+t.objective();String criteria=t==null?"Defina critérios verificáveis.":flow.criteria(t.id()).stream().map(c->"- "+c.description()).reduce("",String::concat);String evidence=t==null?"Sem evidência.":flow.evidence(projectId,t.id()).stream().findFirst().map(TaskEvidence::rawContent).orElse("Sem evidência.");String base="CONTEXTO DO PROJETO\nProjeto: "+p.getName()+"\nObjetivo: "+p.getOriginalIdea()+"\n\nETAPA ATUAL\n"+task+"\n\nCRITÉRIOS DE ACEITE\n"+criteria+"\n\nNÃO REFAÇA\nNão implemente funcionalidades fora da tarefa atual. Não exponha secrets.";String body=switch(type){case FIX_ERROR->"NÃO CONTINUE PARA NOVAS FUNCIONALIDADES.\n\nEstamos corrigindo um erro da tarefa atual.\n\nERRO/EVIDÊNCIA\n"+evidence+"\n\nSINAIS DETECTADOS\n"+flow.latest(t.id()).map(a->String.join(", ",a.signals())).orElse("sem análise")+"\n\nOBJETIVO\nInvestigue a causa raiz e aplique somente a correção necessária.\n\nDEPOIS DA CORREÇÃO\n1. execute novamente o comando que falhou;\n2. execute os testes relacionados;\n3. informe arquivos alterados;\n4. retorne a saída real;\n5. não avance para a próxima feature.";case VALIDATE_RESULT->"A implementação foi reportada como concluída, mas ainda não existe evidência suficiente. Execute build e testes relacionados. Não faça novas funcionalidades. Retorne os resultados completos.";case MODEL_HANDOFF->"PROJECT HANDOFF\nProjeto: "+p.getName()+"\nFase atual: "+Optional.ofNullable(state.state(projectId).currentPhase()).map(x->x.title()).orElse("não definida")+"\nTarefa atual: "+task+"\nÚltima evidência:\n"+evidence+"\nPróxima ação: "+r.title();default->"AO FINAL, RETORNE OBRIGATORIAMENTE\n1. resumo;\n2. arquivos criados;\n3. arquivos alterados;\n4. comandos executados;\n5. build;\n6. testes;\n7. erros;\n8. warnings;\n9. pendências;\n10. próximo passo sugerido.";};return new GeneratedPrompt(type,base+"\n\n"+body,List.of("Project","Task","Acceptance criteria","Latest evidence"),Instant.now());}}
